declare(strict_types=1);
[$a,$b]=$data['players'];$comparisonMetrics=['appearances'=>'出场','starts'=>'首发','goals'=>'进球','assists'=>'助攻','shots'=>'射门','passes_completed'=>'成功传球','ball_progressions'=>'推进','take_ons'=>'过人','interceptions'=>'拦截','tackles_won'=>'成功抢断','clearances'=>'解围'];
$comparisonValue=static fn(array $player,string $key):?float=>in_array($key,['appearances','starts'],true)?(float)$player['summary'][$key]:(isset($player['summary']['totals'][$key])?(float)$player['summary']['totals'][$key]:null);
$chartMetrics=[];foreach($comparisonMetrics as $key=>$label)$chartMetrics[]=['label'=>$label,'left'=>$comparisonValue($a,$key),'right'=>$comparisonValue($b,$key),'suffix'=>''];
$chartMetrics[]=['label'=>'传球成功率','left'=>$a['summary']['pass_completion_pct'],'right'=>$b['summary']['pass_completion_pct'],'suffix'=>'%'];
?>
<section class="wc-panel wc-compare-picker"><div class="wc-section-heading"><div><p class="wc-eyebrow">PLAYER COMPARISON</p><h2>选择两名球员</h2></div><span class="wc-muted">已收录 <?= e($data['ability_coverage']['players']) ?> 名球员的懂球帝能力值</span></div>
<form method="get" action="./" class="wc-compare-form"><input type="hidden" name="view" value="compare"><?php foreach([['player_a',$a],['player_b',$b]] as [$name,$selected]): ?><label><?= $name==='player_a'?'球员 A':'球员 B' ?><input class="wc-player-search" type="search" data-compare-search placeholder="输入中文名、国家队或位置搜索" autocomplete="off" aria-label="搜索<?= $name==='player_a'?'球员 A':'球员 B' ?>"><select name="<?= e($name) ?>" data-compare-select><?php foreach($data['options'] as $option): ?><option value="<?= e($option['id']) ?>" <?= $option['id']===$selected['id']?'selected':'' ?>><?= e(($option['has_ability']?'● ':'').$option['name_zh'].' · '.$option['name'].' · '.($positions[$option['position']]??$option['position'])) ?></option><?php endforeach; ?></select><small class="wc-search-status" aria-live="polite"></small></label><?php endforeach; ?><button class="glass-button" type="submit">开始对比</button></form><p class="wc-muted wc-fineprint">可先输入姓名、国家队或位置缩小下拉名单；● 表示已有可核验的懂球帝综合能力值。</p></section>
<div class="wc-compare-heroes"><?php foreach([$a,$b] as $player): ?><article class="wc-player-hero"><div class="wc-player-identity"><?= $portrait($player,'large') ?><div><p class="wc-eyebrow"><?= e($player['code']) ?> / <?= e($player['position']) ?></p><h2><?= e($player['name']) ?></h2><p><?= $flag($player['code'],$player['name_zh']) ?><?= e($player['name_zh']) ?><span><?= e($player['shirt_number']??'—') ?> 号 · <?= e($positions[$player['position']]??$player['position']) ?></span></p></div></div><strong class="wc-overall-score"><?= $player['ability']?e($player['ability']['overall']):'—' ?><small>综合能力</small></strong></article><?php endforeach; ?></div>
<section class="wc-panel wc-compare-radar"><div class="wc-section-heading"><div><p class="wc-eyebrow">COMPREHENSIVE ABILITY</p><h2>综合能力六维对比</h2></div><span class="wc-muted">固定 0–100 量程</span></div><?php $radarPlayers=[$a,$b];$radarId='compare-ability';require __DIR__.'/player-ability-radar.php'; ?></section>
<section class="wc-panel"><div class="wc-section-heading"><div><p class="wc-eyebrow">TOURNAMENT PERFORMANCE</p><h2>本届世界杯实际表现</h2></div><span class="wc-muted">原始计数，不评判跨位置胜负</span></div>
<div class="wc-compare-chart-legend" aria-label="柱状图颜色说明"><span class="is-a"><i></i>蓝色：<?= e($a['name']) ?></span><span class="is-b"><i></i>橙色：<?= e($b['name']) ?></span></div>
<div class="wc-performance-chart" role="img" aria-label="<?= e($a['name'].'与'.$b['name'].'的本届世界杯实际表现柱状图') ?>"><?php foreach($chartMetrics as $metric):$max=max($metric['left']??0,$metric['right']??0);$leftWidth=$metric['left']===null||$max<=0?0:$metric['left']/$max*100;$rightWidth=$metric['right']===null||$max<=0?0:$metric['right']/$max*100; ?><div class="wc-performance-row"><strong><?= e($metric['label']) ?></strong><div class="wc-performance-bars"><div class="is-a"><span style="--bar:<?= e(round($leftWidth,2)) ?>%"></span><b><?= e($number($metric['left'],$metric['suffix'])) ?></b></div><div class="is-b"><span style="--bar:<?= e(round($rightWidth,2)) ?>%"></span><b><?= e($number($metric['right'],$metric['suffix'])) ?></b></div></div></div><?php endforeach; ?></div>
<div class="wc-table-wrap"><table class="wc-compare-table"><thead><tr><th>指标</th><th><?= e($a['name']) ?></th><th><?= e($b['name']) ?></th></tr></thead><tbody><?php foreach($comparisonMetrics as $key=>$label):$left=in_array($key,['appearances','starts'],true)?$a['summary'][$key]:$a['summary']['totals'][$key];$right=in_array($key,['appearances','starts'],true)?$b['summary'][$key]:$b['summary']['totals'][$key]; ?><tr><th><?= e($label) ?></th><td><?= e($number($left)) ?></td><td><?= e($number($right)) ?></td></tr><?php endforeach; ?><tr><th>传球成功率</th><td><?= e($number($a['summary']['pass_completion_pct'],'%')) ?></td><td><?= e($number($b['summary']['pass_completion_pct'],'%')) ?></td></tr></tbody></table></div><p class="wc-muted wc-fineprint">柱长按每个指标中两人的较大值归一化，仅用于同一指标内对照。— 表示数据源未提供，不视为 0。</p></section>
